            return NotFound();
        Item = item;
        await LoadSuppliersAsync();
        return Page();
    }

    public async Task<IActionResult> OnPostAsync(int? id)
    {
        if (id is not > 0)
            return NotFound();

        Item.RowIndex = id.Value;
