@page
@model InventoryManagement.Pages.Usage.ReportModel
@{
    ViewData["Title"] = "Report Usage";
}

<h1 class="h3 mb-1">Report Component Usage</h1>
<p class="text-body-secondary small mb-3">
    Pick the category, then the specific batch the parts came out of. The quantity
    is deducted from that batch and written to the usage log.
</p>

<form method="post">
    <div asp-validation-summary="ModelOnly" class="text-danger mb-3"></div>

    <div class="card mb-3">
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-4">
                    <label asp-for="Category" class="form-label"></label>
                    <select asp-for="Category" class="form-select" id="categorySelect">
                        <option value="Electronics">Electronics</option>
                        <option value="Electrical">Electrical</option>
                        <option value="Tools">Tools</option>
                        <option value="Modules">Modules</option>
                    </select>
                </div>

                <div class="col-md-8">
                    <label class="form-label">Component batch</label>
                    @*
                        One <select> per category is rendered and all but the active
                        one is disabled, so a disabled select posts nothing. Options
                        are individual batch rows since v2.2.
                    *@
                    @foreach (var kvp in Model.ComponentsByCategory)
                    {
                        <select name="BatchKey" id="sel-@kvp.Key" class="form-select component-select"
                                data-category="@kvp.Key" disabled="@(Model.Category != kvp.Key)">
                            <option value="">-- Select component batch --</option>
                            @foreach (var item in kvp.Value)
                            {
                                var key = InventoryManagement.Pages.Usage.ReportModel.BatchKeyFor(item);
                                <option value="@key" data-remaining="@item.Remaining"
                                        selected="@(key == Model.BatchKey)">
                                    @InventoryManagement.Pages.Usage.ReportModel.BatchLabelFor(item)
                                </option>
                            }
                        </select>
                    }
                    <span asp-validation-for="BatchKey" class="text-danger"></span>
                    <div class="form-text" id="stockHint"></div>
                </div>

                <div class="col-md-4">
                    <label asp-for="QuantityUsed" class="form-label"></label>
                    <input asp-for="QuantityUsed" class="form-control" type="number" min="1" />
                    <span asp-validation-for="QuantityUsed" class="text-danger"></span>
                </div>
                <div class="col-md-4">
                    <label asp-for="UsedDate" class="form-label"></label>
                    <input asp-for="UsedDate" class="form-control" type="date" />
                </div>
                <div class="col-md-4">
                    <label asp-for="Remarks" class="form-label"></label>
                    <input asp-for="Remarks" class="form-control" />
                </div>
            </div>
        </div>
    </div>

