            {
                Database = loaded.Database,
                Modbus = loaded.Modbus,
                Serial = loaded.Serial,
                Ota = loaded.Ota,
                Routes = loaded.Routes,
                Logging = loaded.Logging,
                LoadWarnings = warnings,
            };
        }
        catch (Exception ex)
        {
            return new AppConfig
