            _wasEnabled = _control.Enabled;
            _control.Enabled = false;
        }
    }

    public void Dispose()
    {
        if (_disposed)
            return;

        Cursor.Current = _previousCursor;

        if (_control is not null && !_control.IsDisposed)
            _control.Enabled = _wasEnabled;

        _disposed = true;
    }
}

